class Solution {
public:
    int countPrefixSuffixPairs(vector<string>& words) {
        int n = (int)words.size();
        int ans = 0;
        for (int i = 0; i < n; i++) {
            for (int j = i + 1; j < n; j++) {
                if (isPrefixAndSuffix(words[i], words[j])) {
                    ans++;
                }
            }
        }
        return ans;
    }
private:
    bool isPrefixAndSuffix(const string& str1, const string& str2) {
        int m = (int)str1.size();
        int n = (int)str2.size();
        if (m > n) return false;
        for (int k = 0; k < m; k++) {
            if (str1[k] != str2[k]) return false;
            if (str1[k] != str2[n - m + k]) return false;
        }
        return true;
    }
};
